//! GPT-SoVITS 整合包启动器。
//!
//! Ink 只支持**本地** GSOV, 并由自己负责拉起进程, 以保证参考音频与模型路径
//! 在服务端本机可见。启动方式有四类, 覆盖从"开箱即用"到"完全自定义":
//!
//! * [`LaunchMode::Embedded`] - 整合包自带运行时 (`runtime\python.exe`), 依赖自包含, 默认加 `-I` 隔离;
//! * [`LaunchMode::Conda`] - 复用 conda 环境。用户只需要选环境名 (例如 `gpt-sovits`),
//!   由本模块在磁盘上定位该环境的 `python.exe`。与外部 Python 一样**不能加 `-I`**;
//! * [`LaunchMode::Python`] - 用户自己的 Python (conda / 系统), 直接给解释器路径。
//!   **不能加 `-I`**: 隔离模式会屏蔽用户级 site-packages, 而部分依赖 (如 `click`) 恰恰装在那里;
//! * [`LaunchMode::Command`] - 完全自定义命令 (bat / ps1 / 任意可执行文件), Ink 只负责启动与收尸。

use std::{
    path::{Path, PathBuf},
    process::Command,
};

use serde::{Deserialize, Serialize};

/// 默认端口
pub const DEFAULT_PORT: u16 = 9880;
/// 默认绑定地址 (仅本地)
pub const DEFAULT_HOST: &str = "127.0.0.1";
/// 默认控制脚本
pub const DEFAULT_SCRIPT: &str = "api_v2.py";
/// 默认推理配置
pub const DEFAULT_INFER_CONFIG: &str = "GPT_SoVITS/configs/tts_infer.yaml";

/// 启动方式
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase", tag = "kind")]
pub enum LaunchMode {
    /// 整合包自带运行时
    Embedded { program: String },
    /// conda 环境 (只记录环境名; 解释器路径由 [`LaunchConfig::build_command`] 就地解析)
    Conda {
        /// 环境名, 例如 `gpt-sovits`
        env: String,
        /// 显式指定的解释器路径; 为空时按环境名在磁盘上查找
        #[serde(default)]
        program: Option<String>,
    },
    /// 外部 Python 解释器
    Python { program: String },
    /// 自定义命令 (整条命令直接输入, 不经过 Python 参数拼装)
    Command { command: String },
}

impl LaunchMode {
    /// 是否启用 Python 隔离模式 (`-I`)
    ///
    /// 只有整合包自带运行时才隔离: 外部 Python 与 conda 环境的依赖常常装在用户级
    /// site-packages 里, 加 `-I` 会直接 `ModuleNotFoundError`。
    pub fn isolated(&self) -> bool {
        matches!(self, LaunchMode::Embedded { .. })
    }
}

/// conda 环境 (供界面选择)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct CondaEnv {
    /// 环境名 (传给 `conda run -n <name>` 的那个名字)
    pub name: String,
    /// 面向界面的显示名: 环境名首字母大写 (`base` 例外 —— conda 自己就这么写)
    pub display_name: String,
    /// 该环境的解释器路径 (仅用于展示与兜底)
    pub program: String,
}

/// 在常见位置寻找 conda 环境。
///
/// 刻意不依赖 PATH 上的 `conda`: 图形界面进程未必继承 shell 的初始化脚本。
/// 两路并用 —— `conda env list` 能拿到自建目录里的环境, 直接扫目录能覆盖 conda
/// 本体都找不到的情况。
pub fn list_conda_envs() -> Vec<CondaEnv> {
    let mut envs: Vec<CondaEnv> = Vec::new();

    // 1) `conda env list` 里登记的环境 (包含 `envs_dirs` 指向的自定义目录)
    let exe = conda_executable().unwrap_or_else(|| "conda".into());
    if let Ok(output) = Command::new(exe).args(["env", "list"]).output() {
        let text = String::from_utf8_lossy(&output.stdout).into_owned();
        for line in text.lines() {
            collect_env_line(&mut envs, line);
        }
    }

    // 2) 直接扫描常见安装位置
    for root in conda_roots() {
        if let Some(program) = python_in(&root) {
            let name = root
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or("base")
                .to_string();
            push_env(&mut envs, &name, program);
        }
        // `<root>` 自身可能就是 envs 目录 (`.conda/envs`), 也可能带 `envs` 子目录
        let child_roots = [root.clone(), root.join("envs")];
        for child_root in child_roots {
            let Ok(entries) = std::fs::read_dir(&child_root) else {
                continue;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if !path.is_dir() {
                    continue;
                }
                let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                    continue;
                };
                if let Some(program) = python_in(&path) {
                    push_env(&mut envs, name, program);
                }
            }
        }
    }

    envs.sort_by_key(|env| env.name.to_lowercase());
    envs.dedup_by(|a, b| a.name == b.name);
    envs
}

/// 解析 `conda env list` 的一行 (`<name>  <path>` 或 `# ...`)
fn collect_env_line(envs: &mut Vec<CondaEnv>, line: &str) {
    let line = line.trim();
    if line.is_empty() || line.starts_with('#') {
        return;
    }
    // 最后一段是路径, 前面是环境名 (名字本身可能含空格)
    let Some(index) = line.rfind(char::is_whitespace) else {
        return;
    };
    let (name, path) = line.split_at(index);
    let name = name.trim();
    let Some(program) = python_in(Path::new(path.trim())) else {
        return;
    };
    push_env(envs, name, program);
}

/// 在给定环境中寻找解释器
fn python_in(prefix: &Path) -> Option<String> {
    for candidate in ["python.exe", "bin/python3", "bin/python"] {
        let path = prefix.join(candidate);
        if path.is_file() {
            return Some(path.to_string_lossy().into_owned());
        }
    }
    None
}

fn push_env(envs: &mut Vec<CondaEnv>, name: &str, program: String) {
    let name = name.trim();
    if name.is_empty() {
        return;
    }
    envs.push(CondaEnv {
        name: name.to_string(),
        display_name: display_env_name(name),
        program,
    });
}

/// 环境名的显示形式: 首字母大写, `base` 保持原样 (与 conda 自己的写法一致)
fn display_env_name(name: &str) -> String {
    if name.eq_ignore_ascii_case("base") {
        return "base".to_string();
    }
    let mut chars = name.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => name.to_string(),
    }
}

/// 按环境名解析解释器: 先看 `CONDA_*` 指向的根, 再按常见位置拼路径
fn resolve_conda_program(env: &str) -> Option<String> {
    let env = env.trim();
    if env.is_empty() {
        return None;
    }
    // 环境名本身可能是路径
    let as_path = PathBuf::from(env);
    if as_path.is_dir() {
        if let Some(program) = python_in(&as_path) {
            return Some(program);
        }
    }

    let mut roots: Vec<PathBuf> = Vec::new();
    for key in ["CONDA_ENVS_PATH", "CONDA_ROOT", "CONDA_PREFIX"] {
        if let Ok(value) = std::env::var(key) {
            if !value.is_empty() {
                roots.push(PathBuf::from(value));
            }
        }
    }
    if let Some(home) = std::env::var_os("USERPROFILE").or_else(|| std::env::var_os("HOME")) {
        let home = PathBuf::from(home);
        for tool in ["miniconda3", "anaconda3", "miniforge3", "mambaforge"] {
            roots.push(home.join(tool));
        }
    }
    for drive in ["C:", "D:", "E:"] {
        for tool in ["miniconda3", "anaconda3", "miniforge3", "mambaforge"] {
            roots.push(PathBuf::from(format!("{drive}\\{tool}")));
        }
    }

    const DEFAULT_ENV_NAMES: [&str; 2] = ["base", "root"];
    for root in roots {
        let bases: [&Path; 2] = [root.as_path(), &root.join("envs")];
        for base in bases {
            let candidate = if DEFAULT_ENV_NAMES.contains(&env) {
                base.to_path_buf()
            } else {
                base.join(env)
            };
            if let Some(program) = python_in(&candidate) {
                return Some(program);
            }
        }
    }
    None
}

