/// 整合包探测结果 (供 UI 预填默认值)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct DetectedRuntime {
    /// 是否为可用的整合包根目录
    pub valid: bool,
    /// 内置运行时路径
    pub embedded_python: Option<String>,
    /// 内置运行时是否存在
    pub has_embedded_python: bool,
    /// 控制脚本是否存在
    pub has_script: bool,
    /// 推理配置是否存在
    pub has_infer_config: bool,
    /// 探测到的问题 (供 UI 提示)
    pub issues: Vec<String>,
}

/// 探测整合包目录, 给出默认启动配置所需的全部信息
pub fn detect(root: &Path) -> DetectedRuntime {
    let mut issues = Vec::new();

    if !root.is_dir() {
        return DetectedRuntime {
            valid: false,
            embedded_python: None,
            has_embedded_python: false,
            has_script: false,
            has_infer_config: false,
            issues: vec!["目录不存在".into()],
        };
    }

    let embedded = root.join("runtime").join("python.exe");
    let has_embedded = embedded.is_file();
    if !has_embedded {
        issues.push(
            "未见整合包内置运行时 (runtime\\python.exe), 请指定外部 Python 或自定义命令".into(),
        );
    }

    let has_script = root.join(DEFAULT_SCRIPT).is_file();
    if !has_script {
        issues.push(format!("未见控制脚本 {DEFAULT_SCRIPT}"));
    }

    let has_infer_config = root.join(DEFAULT_INFER_CONFIG).is_file();
    if !has_infer_config {
        issues.push(format!("未见推理配置 {DEFAULT_INFER_CONFIG}"));
    }

    DetectedRuntime {
        valid: has_script,
        embedded_python: has_embedded.then(|| embedded.display().to_string()),
        has_embedded_python: has_embedded,
        has_script,
        has_infer_config,
        issues,
    }
}

/// 候选 GSOV 模型 (一整套 GPT + SoVITS 权重)
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCandidate {
    /// 推断的角色名 (由权重文件名归一化而来)
    pub name: String,
    /// 配对用的归一化键 (去掉训练后缀与扩展名, 全小写)
    ///
    /// 界面按角色名自动配模型时用它来比对: 展示名 (`name`) 带 `-e15` 这类训练后缀,
    /// 直接比会匹配不上; 而把这个规则复制到前端就等于把命名约定写两遍。
    pub key: String,
    /// GPT (T2S) 权重路径, 相对整合包根, 正斜杠分隔
    pub gpt_weights: String,
    /// SoVITS 权重路径, 相对整合包根, 正斜杠分隔
    pub sovits_weights: String,
}

/// 扫描整合包内的权重目录, 推断出可用的模型组合。
///
/// GPT-SoVITS 的权重目录命名约定为 `GPT_weights[_vN]` 与 `SoVITS_weights[_vN]`,
/// 训练产物文件名通常是「角色名 + 训练步数字段」(如 `爱音-e15.ckpt` 与
/// `爱音_e4_s436_l64.pth`)。这里按**归一化后的公共前缀**配对, 只返回两边都存在的组合,
/// 因此不会给出无法使用的建议。仅支持 v4: `_v2` / `_v3` 目录会被跳过。
pub fn scan_models(root: &Path) -> Vec<ModelCandidate> {
    let debug = std::env::var("WEBGAL_INK_DEBUG_SCAN").is_ok();
    let mut gpt_files: Vec<(String, String)> = Vec::new(); // (归一化名, 相对路径)
    let mut sovits_files: Vec<(String, String)> = Vec::new();

    let top = read_dir_entries(root);
    if debug {
        eprintln!("[scan] root={} entries={}", root.display(), top.len());
    }

    for entry in top {
        let name = entry.file_name;
        let is_gpt = name.starts_with("GPT_weights");
        let is_sovits = name.starts_with("SoVITS_weights");
        if debug {
            eprintln!("[scan] name={name:?} gpt={is_gpt} sovits={is_sovits}");
        }
        let is_sovits = name.starts_with("SoVITS_weights");
        if !is_gpt && !is_sovits {
            continue;
        }
        // 仅 v4: 无版本后缀, 或后缀恰为 `_v4`; 显式跳过 v1/v2/v3 等旧版本目录
        if let Some((_, suffix)) = name.rsplit_once("_v") {
            if !suffix.is_empty() && suffix != "4" && suffix.chars().all(|ch| ch.is_ascii_digit()) {
                continue;
            }
        }

        for file in read_dir_entries(&root.join(&name)) {
            if !file.is_file {
                continue;
            }
            let extension = file
                .file_name
                .rsplit_once('.')
                .map(|(_, ext)| ext.to_ascii_lowercase())
                .unwrap_or_default();
            let expected = if is_gpt { "ckpt" } else { "pth" };
            if extension != expected {
                continue;
            }
            let relative = format!("{}/{}", name, file.file_name);
            let key = normalize_model_name(&file.file_name);
            if is_gpt {
                gpt_files.push((key, relative));
            } else {
                sovits_files.push((key, relative));
            }
        }
    }

    let mut candidates = Vec::new();
    for (gpt_key, gpt_weights) in &gpt_files {
        // 选取归一化名匹配度最高的 SoVITS 权重: 互为前缀即视为同一角色
        let best = sovits_files
            .iter()
            .filter(|(sovits_key, _)| {
                !sovits_key.is_empty()
                    && !gpt_key.is_empty()
                    && (gpt_key.starts_with(sovits_key.as_str())
                        || sovits_key.starts_with(gpt_key.as_str()))
            })
            .max_by_key(|(sovits_key, _)| sovits_key.len().min(gpt_key.len()));
        let Some((_, sovits_weights)) = best else {
            continue;
        };
        candidates.push(ModelCandidate {
            name: display_model_name(gpt_weights),
            key: gpt_key.clone(),
            gpt_weights: gpt_weights.clone(),
            sovits_weights: sovits_weights.clone(),
        });
    }

    candidates.sort_by(|a, b| a.name.cmp(&b.name));
    candidates
}

/// 去掉训练后缀与扩展名, 得到用于配对的归一化名
fn normalize_model_name(file_name: &str) -> String {
    let stem = file_name
        .rsplit_once('.')
        .map(|(stem, _)| stem)
        .unwrap_or(file_name);
    let mut result = String::new();
    for ch in stem.chars() {
        // 训练后缀形如 `-e15` / `_e4_s436_l64`, 遇到 `-` 或 `_` 即截断
        if ch == '-' || ch == '_' {
            break;
        }
        result.push(ch);
    }
    result.trim().to_lowercase()
}

/// 展示用名称: 权重文件的主干名
fn display_model_name(relative: &str) -> String {
    relative
        .rsplit('/')
        .next()
        .unwrap_or(relative)
        .rsplit_once('.')
        .map(|(stem, _)| stem)
        .unwrap_or(relative)
        .to_string()
}

/// 目录项
struct DirEntryName {
    file_name: String,
    is_file: bool,
}

fn read_dir_entries(dir: &Path) -> Vec<DirEntryName> {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    entries
        .filter_map(Result::ok)
        .map(|entry| DirEntryName {
            file_name: entry.file_name().to_string_lossy().to_string(),
            is_file: entry
                .file_type()
                .map(|kind| kind.is_file())
                .unwrap_or(false),
        })
        .collect()
}

/// 定位 conda 本体 (命令行程序)。
///
/// 一定要走 `conda run` 而不是直接调用环境的 `python.exe`: 直接调用不会加载环境的
/// 激活脚本 (Windows 上是 `Library\bin` 等路径), 于是环境里明明装了 numpy 也会
/// `ModuleNotFoundError` —— 而在 Anaconda Prompt 里跑 `webui.py` 却正常。
pub fn conda_executable() -> Option<String> {
    if let Ok(prefix) = std::env::var("CONDA_EXE") {
        if !prefix.trim().is_empty() {
            return Some(prefix);
        }
    }
    let roots = conda_roots();
    for root in &roots {
        for candidate in [
            root.join("Scripts").join("conda.exe"),
            root.join("condabin").join("conda.bat"),
        ] {
            if candidate.is_file() {
                return Some(candidate.to_string_lossy().into_owned());
            }
        }
    }
    // 环境目录 (`.conda/envs/<name>`) 的祖先是 `.conda`, 其中通常也带一份 conda
    for root in &roots {
        if let Some(parent) = root.parent() {
            let candidate = parent.join("Scripts").join("conda.exe");
            if candidate.is_file() {
                return Some(candidate.to_string_lossy().into_owned());
            }
        }
    }
    None
}

/// conda 根目录候选 (`<root>` 与 `<root>\envs` 都由调用方拼装)
fn conda_roots() -> Vec<PathBuf> {
    let mut roots = Vec::new();
    for key in ["CONDA_ROOT", "CONDA_PREFIX"] {
        if let Ok(value) = std::env::var(key) {
            if !value.trim().is_empty() {
                roots.push(PathBuf::from(value));
            }
        }
    }
    if let Ok(value) = std::env::var("CONDA_ENVS_PATH") {
        for part in value.split(';').filter(|part| !part.trim().is_empty()) {
            roots.push(PathBuf::from(part.trim()));
        }
    }
    if let Some(home) = std::env::var_os("USERPROFILE").or_else(|| std::env::var_os("HOME")) {
        let home = PathBuf::from(home);
        for tool in [
            ".conda",
            "miniconda3",
            "anaconda3",
            "miniforge3",
            "mambaforge",
        ] {
            roots.push(home.join(tool));
        }
    }
    for base in [r"C:\ProgramData\miniconda3", r"C:\ProgramData\anaconda3"] {
        roots.push(PathBuf::from(base));
    }
    for drive in ["C:", "D:", "E:"] {
        for tool in ["miniconda3", "anaconda3", "miniforge3", "mambaforge"] {
            roots.push(PathBuf::from(format!("{drive}\\{tool}")));
        }
    }
    roots
}

/// 按探测结果构造默认启动配置
pub fn default_config(root: &Path, detected: &DetectedRuntime) -> LaunchConfig {
    let mode = match &detected.embedded_python {
        Some(program) => LaunchMode::Embedded {
            program: program.clone(),
        },
        None => LaunchMode::Python {
            program: "python".into(),
        },
    };
    LaunchConfig {
        root: root.display().to_string(),
        mode,
        host: DEFAULT_HOST.into(),
        port: DEFAULT_PORT,
        script: DEFAULT_SCRIPT.into(),
        infer_config: DEFAULT_INFER_CONFIG.into(),
        extra_args: Vec::new(),
    }
}

/// 启动命令
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LaunchCommand {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

impl LaunchConfig {
    /// 拼装实际启动命令
    pub fn build_command(&self) -> LaunchCommand {
        let cwd = PathBuf::from(&self.root);
        // 传给 api_v2.py 的参数 (自定义命令不使用)
        let script_args = |config: &LaunchConfig| {
            let mut args: Vec<String> = Vec::new();
            if config.mode.isolated() {
                args.push("-I".into());
            }
            args.push(config.script.clone());
            args.push("-a".into());
            args.push(config.host.clone());
            args.push("-p".into());
            args.push(config.port.to_string());
            args.push("-c".into());
            args.push(config.infer_config.clone());
            args.extend(config.extra_args.iter().cloned());
            args
        };

        let (program, args) = match &self.mode {
            LaunchMode::Embedded { program } | LaunchMode::Python { program } => {
                (program.clone(), script_args(self))
            }
            /*
             * conda 环境必须走 `conda run`。
             *
             * 直接调用 `<env>\python.exe` **不会**加载环境的激活脚本 (Windows 上是
             * `Library\bin`、`Scripts` 等路径), 于是环境里明明装了 numpy 也会
             * `ModuleNotFoundError` —— 而在 Anaconda Prompt 里跑 webui 却一切正常。
             * `conda run` 会先完成激活再执行 python, 与用户手动激活的语义一致。
             */
            LaunchMode::Conda { env, program } => match conda_executable() {
                Some(conda) => {
                    let mut args = vec![
                        "run".to_string(),
                        "-n".to_string(),
                        env.clone(),
                        "--no-capture-output".to_string(),
                        "python".to_string(),
                    ];
                    args.extend(script_args(self));
                    (conda, args)
                }
                // 找不到 conda 本体时退化为直接调用该环境的解释器 (至少路径是对的)
                None => {
                    let resolved = program
                        .clone()
                        .filter(|path| !path.trim().is_empty())
                        .or_else(|| resolve_conda_program(env))
                        .unwrap_or_else(|| "python".into());
                    (resolved, script_args(self))
                }
            },
            // 自定义命令是**一整条命令**, 这里按命令行惯例切分 (支持引号包裹的路径)
            LaunchMode::Command { command } => {
                let mut parts = split_command(command);
                if parts.is_empty() {
                    (command.clone(), Vec::new())
                } else {
                    let program = parts.remove(0);
                    (program, parts)
                }
            }
        };
        LaunchCommand { program, args, cwd }
    }
}

/// 把一整条命令行切成程序与参数。
///
/// 只处理引号与空白 (不展开环境变量、不处理管道) —— 需要这些的场景应当写成一个
/// 脚本文件再填它的路径。
fn split_command(command: &str) -> Vec<String> {
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut quote: Option<char> = None;

    for ch in command.trim().chars() {
        match ch {
            '"' | '\'' if quote.is_none() => quote = Some(ch),
            ch if Some(ch) == quote => quote = None,
            ch if ch.is_whitespace() && quote.is_none() => {
                if !current.is_empty() {
                    parts.push(std::mem::take(&mut current));
                }
            }
            ch => current.push(ch),
        }
    }
    if !current.is_empty() {
        parts.push(current);
    }
    parts
}

/// 用于日志面板的换行切分。
///
/// GSOV 依赖的 `tqdm` 进度条用 `\r` 覆盖同一行且**不换行**, 直接按 `\n` 收集会把
/// 整个推理过程的进度条拼成一条超长文本。这里按 `\n` / `\r` 任意一个切分, 并忽略空段。
#[derive(Debug, Default)]
pub struct LineSplitter {
    buffer: String,
}

impl LineSplitter {
    pub fn new() -> Self {
        Self::default()
    }

    /// 送入一段输出, 返回其中完整的行
    pub fn push(&mut self, chunk: &str) -> Vec<String> {
        let mut lines = Vec::new();
        for ch in chunk.chars() {
            match ch {
                '\n' | '\r' => {
                    let line = std::mem::take(&mut self.buffer);
                    let trimmed = line.trim();
                    if !trimmed.is_empty() {
                        lines.push(trimmed.to_string());
                    }
                }
                other => {
                    self.buffer.push(other);
                    // 防御性截断: 进度条可能极长且无分隔符
                    if self.buffer.len() > 4096 {
                        let line = std::mem::take(&mut self.buffer);
                        lines.push(line);
                    }
                }
            }
        }
        lines
    }

    /// 取走缓冲区中的残留内容 (进程结束时调用)
    pub fn flush(&mut self) -> Option<String> {
        let line = std::mem::take(&mut self.buffer);
        let trimmed = line.trim();
        (!trimmed.is_empty()).then(|| trimmed.to_string())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(mode: LaunchMode) -> LaunchConfig {
        LaunchConfig {
            root: "C:/gsov".into(),
            mode,
            host: DEFAULT_HOST.into(),
            port: DEFAULT_PORT,
            script: DEFAULT_SCRIPT.into(),
            infer_config: DEFAULT_INFER_CONFIG.into(),
            extra_args: Vec::new(),
        }
    }

    #[test]
    fn embedded_mode_adds_isolation_flag() {
        let command = config(LaunchMode::Embedded {
            program: "C:/gsov/runtime/python.exe".into(),
        })
        .build_command();
        assert_eq!(command.program, "C:/gsov/runtime/python.exe");
        assert_eq!(command.args[0], "-I");
        assert!(command.args.contains(&"api_v2.py".to_string()));
        assert!(command.args.contains(&"9880".to_string()));
        assert_eq!(command.cwd, PathBuf::from("C:/gsov"));
    }

    #[test]
    fn external_python_must_not_isolate() {
        // 用户级 site-packages 里可能装着 click 等依赖, 加 -I 会导致 ModuleNotFoundError
        let command = config(LaunchMode::Python {
            program: "C:/conda/envs/gpt-sovits/python.exe".into(),
        })
        .build_command();
        assert!(!command.args.contains(&"-I".to_string()));
        assert_eq!(command.args[0], "api_v2.py");
    }

    #[test]
    fn command_mode_splits_whole_command_line() {
        // 自定义命令是**一整条命令**, 由这里按命令行惯例切分
        let command = config(LaunchMode::Command {
            command: "C:/gsov/start.bat --port 1234".into(),
        })
        .build_command();
        assert_eq!(command.program, "C:/gsov/start.bat");
        assert_eq!(command.args, vec!["--port".to_string(), "1234".to_string()]);
    }

    #[test]
    fn command_mode_keeps_quoted_program_path_together() {
        let command = config(LaunchMode::Command {
            command: r#""C:/Program Files/gsov/start.bat" -a 127.0.0.1"#.into(),
        })
        .build_command();
        assert_eq!(command.program, "C:/Program Files/gsov/start.bat");
        assert_eq!(
            command.args,
            vec!["-a".to_string(), "127.0.0.1".to_string()]
        );
    }

    #[test]
    fn conda_mode_runs_through_conda_so_the_env_is_activated() {
        // 必须走 `conda run`: 直接调用环境的 python.exe 不会激活环境,
        // 环境里装好的 numpy 会变成 ModuleNotFoundError (用户实际遇到的报错)。
        let command = config(LaunchMode::Conda {
            env: "gpt-sovits".into(),
            program: Some("D:/conda/envs/gpt-sovits/python.exe".into()),
        })
        .build_command();
        // conda 与外部 Python 一样不能加 -I
        assert!(!command.args.contains(&"-I".to_string()));
        if let Some(expected) = conda_executable() {
            assert_eq!(command.program, expected);
            assert_eq!(
                &command.args[..5],
                ["run", "-n", "gpt-sovits", "--no-capture-output", "python"]
            );
        } else {
            // 本机没有 conda 本体时退化为直接调用环境解释器
            assert_eq!(command.program, "D:/conda/envs/gpt-sovits/python.exe");
        }
        assert!(command.args.contains(&"api_v2.py".to_string()));
    }

    #[test]
    fn conda_mode_without_program_falls_back_to_python() {
        // 环境名在本机找不到时不能崩, 退化成 PATH 上的 python (随后启动失败会有可读日志)
        let command = config(LaunchMode::Conda {
            env: "definitely-not-a-real-env-xyz".into(),
            program: None,
        })
        .build_command();
        assert!(!command.program.is_empty());
        assert!(!command.args.contains(&"-I".to_string()));
    }

    #[test]
    fn extra_args_are_appended_after_defaults() {
        let mut launch = config(LaunchMode::Python {
            program: "python".into(),
        });
        launch.extra_args = vec!["--language".into(), "zh".into()];
        let command = launch.build_command();
        let tail: Vec<_> = command.args.iter().rev().take(2).cloned().collect();
        assert_eq!(tail, vec!["zh".to_string(), "--language".to_string()]);
    }

    #[test]
    fn detect_reports_missing_directory() {
        let detected = detect(Path::new("C:/definitely/not/here/gsov"));
        assert!(!detected.valid);
        assert!(!detected.issues.is_empty());
    }

    #[test]
    fn detect_finds_embedded_runtime() {
        let root = std::env::temp_dir().join("webgal-ink-detect-ok");
        std::fs::create_dir_all(root.join("runtime")).unwrap();
        std::fs::create_dir_all(root.join("GPT_SoVITS/configs")).unwrap();
        std::fs::write(root.join("runtime/python.exe"), b"").unwrap();
        std::fs::write(root.join("api_v2.py"), b"").unwrap();
        std::fs::write(root.join("GPT_SoVITS/configs/tts_infer.yaml"), b"").unwrap();

        let detected = detect(&root);
        assert!(detected.valid);
        assert!(detected.has_embedded_python);
        assert!(detected.has_script);
        assert!(detected.has_infer_config);
        assert!(detected.issues.is_empty());

        let default = default_config(&root, &detected);
        assert!(matches!(default.mode, LaunchMode::Embedded { .. }));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn detect_without_runtime_suggests_external_python() {
        let root = std::env::temp_dir().join("webgal-ink-detect-no-runtime");
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join("api_v2.py"), b"").unwrap();

        let detected = detect(&root);
        assert!(detected.valid);
        assert!(!detected.has_embedded_python);
        let default = default_config(&root, &detected);
        assert!(matches!(default.mode, LaunchMode::Python { .. }));
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn splitter_handles_carriage_return_progress() {
        let mut splitter = LineSplitter::new();
        assert!(splitter.push("0%|          | 0/1500").is_empty());
        let lines = splitter.push("\r  1%|>         | 20/1500\r");
        assert_eq!(
            lines,
            vec!["0%|          | 0/1500", "1%|>         | 20/1500"]
        );
        assert!(splitter.push("  50%|").is_empty());
        assert_eq!(splitter.flush().as_deref(), Some("50%|"));
    }

    #[test]
    fn splitter_handles_newlines_and_ignores_blanks() {
        let mut splitter = LineSplitter::new();
        let lines = splitter.push("Loading Text2Semantic weights\n\nINFO: ready\n");
        assert_eq!(lines, vec!["Loading Text2Semantic weights", "INFO: ready"]);
        assert!(splitter.flush().is_none());
    }

    // -------- 模型扫描 --------

    fn temp_root(name: &str) -> PathBuf {
        let root = std::env::temp_dir()
            .join("webgal-ink-model-scan")
            .join(name);
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&root).unwrap();
        root
    }

    fn touch(root: &Path, relative: &str) {
        let path = root.join(relative.replace('/', std::path::MAIN_SEPARATOR_STR));
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, b"x").unwrap();
    }

    #[test]
    fn scan_pairs_gpt_and_sovits_by_common_prefix() {
        let root = temp_root("pair");
        touch(&root, "GPT_weights_v4/爱音-e15.ckpt");
        touch(&root, "SoVITS_weights_v4/爱音_e4_s436_l64.pth");
        touch(&root, "GPT_weights_v4/素世(夹)-e15.ckpt");
        touch(&root, "SoVITS_weights_v4/素世(夹)_e4_s512_l64.pth");

        eprintln!("[test] debug_root={}", root.display());
        eprintln!("[test] is_dir={}", root.is_dir());
        eprintln!(
            "[test] top entries={:?}",
            std::fs::read_dir(&root).map(|r| r.count())
        );

        let candidates = scan_models(&root);
        assert_eq!(candidates.len(), 2);
        // 按名称排序
        assert_eq!(candidates[0].gpt_weights, "GPT_weights_v4/爱音-e15.ckpt");
        assert_eq!(
            candidates[0].sovits_weights,
            "SoVITS_weights_v4/爱音_e4_s436_l64.pth"
        );
        assert_eq!(candidates[0].name, "爱音-e15");
        // 配对键去掉了训练后缀: 界面按角色名自动配模型时用它
        assert_eq!(candidates[0].key, "爱音");
        assert_eq!(candidates[1].key, "素世(夹)");
        assert_eq!(
            candidates[1].gpt_weights,
            "GPT_weights_v4/素世(夹)-e15.ckpt"
        );
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn scan_skips_non_v4_weight_directories() {
        let root = temp_root("skip-old");
        // 文件名刻意不互为前缀, 避免与 "旧目录被跳过" 的断言混在一起
        touch(&root, "GPT_weights/onlygpt-e15.ckpt");
        touch(&root, "SoVITS_weights/onlysovits_e4.pth");
        touch(&root, "GPT_weights_v2/onlygpt2-e15.ckpt");
        touch(&root, "SoVITS_weights_v3/onlysovits3_e4.pth");
        assert!(scan_models(&root).is_empty());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn scan_accepts_unsuffixed_v4_directories() {
        // 部分整合包直接用 `GPT_weights` / `SoVITS_weights` 存放 v4 权重
        let root = temp_root("no-suffix");
        touch(&root, "GPT_weights/anon-e10.ckpt");
        touch(&root, "SoVITS_weights/anon_e4_s100.pth");
        let candidates = scan_models(&root);
        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0].gpt_weights, "GPT_weights/anon-e10.ckpt");
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn scan_ignores_unpaired_weights() {
        let root = temp_root("unpaired");
        touch(&root, "GPT_weights_v4/仅有gpt-e15.ckpt");
        touch(&root, "SoVITS_weights_v4/另一个角色_e4.pth");
        assert!(scan_models(&root).is_empty());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn scan_ignores_wrong_extensions() {
        let root = temp_root("extensions");
        touch(&root, "GPT_weights_v4/anon-e15.ckpt");
        touch(&root, "GPT_weights_v4/notes.txt");
        touch(&root, "SoVITS_weights_v4/anon_e4.pth");
        touch(&root, "SoVITS_weights_v4/readme.md");
        let candidates = scan_models(&root);
        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0].gpt_weights, "GPT_weights_v4/anon-e15.ckpt");
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn scan_missing_directories_is_empty() {
        let root = temp_root("empty");
        assert!(scan_models(&root).is_empty());
        assert!(scan_models(Path::new("C:/definitely/not/here")).is_empty());
        let _ = std::fs::remove_dir_all(&root);
    }

    #[test]
    fn normalize_model_name_drops_training_suffix() {
        assert_eq!(normalize_model_name("爱音-e15.ckpt"), "爱音");
        assert_eq!(normalize_model_name("爱音_e4_s436_l64.pth"), "爱音");
        assert_eq!(normalize_model_name("素世(夹)-e15.ckpt"), "素世(夹)");
        assert_eq!(normalize_model_name("Anon_e4.pth"), "anon");
        assert_eq!(normalize_model_name("no-extension"), "no");
    }
}
